using System;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Threading.Tasks;using System.Web.Script.Serialization;using System.Windows.Forms;using Microsoft.Web.WebView2.Core;using Microsoft.Web.WebView2.WinForms;
sealed class SpotifyHost:IDisposable{
 readonly Form owner;readonly string profile;Form window;WebView2 view;int sequence;readonly Dictionary<int,TaskCompletionSource<object>> pending=new Dictionary<int,TaskCompletionSource<object>>();readonly JavaScriptSerializer json=new JavaScriptSerializer{MaxJsonLength=4*1024*1024};bool disposed;
 public SpotifyHost(Form owner,string profile){this.owner=owner;this.profile=profile;}
 static bool Allowed(string address){Uri u;return Uri.TryCreate(address,UriKind.Absolute,out u)&&u.Scheme=="https"&&(u.Host=="open.spotify.com"||u.Host=="accounts.spotify.com");}
 public async Task<object> Handle(Dictionary<string,object> request){string action=Convert.ToString(request["op"]).Substring(8);if(action=="open"){await Open(true);return new{ok=true};}if(view==null&&action=="pause")return new{ok=true};if(view==null){await Open(false);if(action=="status")return new{connected=false,message="Carregando Spotify. Entre na sua conta se solicitado."};for(int i=0;i<40;i++){if(await view.ExecuteScriptAsync("!!window.NoctuneSpotify")=="true")break;await Task.Delay(500);}}if(action=="logout"){try{await Send(new Dictionary<string,object>{{"action","pause"}});}catch{}await view.CoreWebView2.Profile.ClearBrowsingDataAsync(CoreWebView2BrowsingDataKinds.Cookies);view.CoreWebView2.Navigate("https://open.spotify.com/");return new{ok=true};}var data=new Dictionary<string,object>(request);data.Remove("requestId");data.Remove("op");data["action"]=action;return await Send(data);}
 async Task Open(bool visible){if(disposed)throw new ObjectDisposedException("SpotifyHost");if(window!=null){if(visible){window.Show(owner);window.Activate();}return;}window=new Form{Text="Conectar Spotify · Noctune",Size=new Size(1080,780),MinimumSize=new Size(600,500),StartPosition=FormStartPosition.CenterParent,BackColor=Color.Black};view=new WebView2{Dock=DockStyle.Fill,DefaultBackgroundColor=Color.Black};window.Controls.Add(view);window.FormClosing+=(s,e)=>{if(!disposed&&e.CloseReason==CloseReason.UserClosing){e.Cancel=true;window.Hide();}};window.ShowInTaskbar=visible;window.Opacity=visible?1:0;window.Show(owner);try{var env=await CoreWebView2Environment.CreateAsync(null,profile,new CoreWebView2EnvironmentOptions("--autoplay-policy=no-user-gesture-required"));await view.EnsureCoreWebView2Async(env);var core=view.CoreWebView2;core.Settings.AreDevToolsEnabled=false;core.Settings.IsStatusBarEnabled=false;core.Settings.IsPasswordAutosaveEnabled=false;core.Settings.IsGeneralAutofillEnabled=false;core.NavigationStarting+=(s,e)=>{if(!Allowed(e.Uri))e.Cancel=true;};core.NewWindowRequested+=(s,e)=>{if(Allowed(e.Uri))e.NewWindow=core;else e.Handled=true;};core.PermissionRequested+=(s,e)=>{e.State=e.PermissionKind==CoreWebView2PermissionKind.Autoplay?CoreWebView2PermissionState.Allow:CoreWebView2PermissionState.Deny;};core.DownloadStarting+=(s,e)=>e.Cancel=true;core.WebMessageReceived+=(s,e)=>{Uri u;if(!Uri.TryCreate(e.Source,UriKind.Absolute,out u)||u.Scheme!="https"||u.Host!="open.spotify.com")return;try{var message=json.Deserialize<Dictionary<string,object>>(e.WebMessageAsJson);if(!message.ContainsKey("noctuneSpotifyResult"))return;int id=Convert.ToInt32(message["id"]);TaskCompletionSource<object> task;if(pending.TryGetValue(id,out task)){pending.Remove(id);task.TrySetResult(message["value"]);}}catch{}};await core.AddScriptToExecuteOnDocumentCreatedAsync(File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"web","spotify-page.js")));core.Navigate("https://open.spotify.com/");if(!visible){window.Hide();window.Opacity=1;window.ShowInTaskbar=true;}}catch{Dispose();throw;}}
 async Task<object> Send(Dictionary<string,object> data){if(view.CoreWebView2==null)throw new Exception("Aguarde a janela do Spotify carregar.");int id=++sequence;var reply=new TaskCompletionSource<object>();pending[id]=reply;string script="(async()=>{let value;try{value=window.NoctuneSpotify?await window.NoctuneSpotify.run("+json.Serialize(data)+"):{error:'Aguarde o Spotify carregar e entre na sua conta.'};}catch(e){value={error:'O Spotify não respondeu.'};}window.chrome.webview.postMessage({noctuneSpotifyResult:true,id:"+id+",value});})()";try{await view.ExecuteScriptAsync(script);if(await Task.WhenAny(reply.Task,Task.Delay(25000))!=reply.Task)throw new Exception("O Spotify demorou a responder. Abra Conectar Spotify e tente novamente.");return await reply.Task;}finally{pending.Remove(id);}}
 public void Dispose(){disposed=true;foreach(var p in new List<TaskCompletionSource<object>>(pending.Values))p.TrySetCanceled();pending.Clear();if(window!=null)window.Dispose();window=null;view=null;}
}
